-- AZ retry quote promotion 2026-07-13 - Marquez 3 R&R picks (campaign platform, source-verified verbatim)
BEGIN;

-- Aaron Márquez / voting-rights=1
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at)
SELECT '0df9cd85-3923-48bd-86c2-b7d4b31d510d', 'voting-rights', $q$Aaron supports Automatic Voter Registration, Free State IDs, Same Day Registration, Expanded Early Voting up to Election Day, and Counting Ballots Postmarked by Election Day.$q$, $q$[The candidate] supports Automatic Voter Registration, Free State IDs, Same Day Registration, Expanded Early Voting up to Election Day, and Counting Ballots Postmarked by Election Day.$q$, 'https://www.aaronmarquez.com/issues', 'Aaron Marquez campaign site', true, $q$Verbatim from the candidate's own campaign issues page; only edit was replacing his first name with a bracketed placeholder so the quote can't identify the speaker. Cited because it lists the specific ballot-access reforms (automatic registration, same-day registration, expanded early voting) that anchor the most expansive chair on the voting-rights scale.$q$, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0df9cd85-3923-48bd-86c2-b7d4b31d510d' AND topic_key='voting-rights' AND quote_text=$q$Aaron supports Automatic Voter Registration, Free State IDs, Same Day Registration, Expanded Early Voting up to Election Day, and Counting Ballots Postmarked by Election Day.$q$);

-- Aaron Márquez / trans-athletes=1
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at)
SELECT '0df9cd85-3923-48bd-86c2-b7d4b31d510d', 'trans-athletes', $q$Especially with the recent attack on transgender student-athletes with the passage of SB 1165, the Arizona State Legislature is actively perpetuating discrimination in our schools, and as a state representative, I will fight to remove and prevent measures that discriminate against marginalized students.$q$, $q$Especially with the recent attack on transgender student-athletes with the passage of SB 1165, the Arizona State Legislature is actively perpetuating discrimination in our schools, and… I will fight to remove and prevent measures that discriminate against marginalized students.$q$, 'https://www.aaronmarquez.com/issues', 'Aaron Marquez campaign site', true, $q$Verbatim from the candidate's own campaign issues page; only edit was cutting the office self-reference ("as a state representative," replaced with an ellipsis). Cited because it explicitly opposes SB1165's restriction on transgender athletes and commits to reversing such measures, matching the most inclusive chair on the trans-athletes scale.$q$, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0df9cd85-3923-48bd-86c2-b7d4b31d510d' AND topic_key='trans-athletes' AND quote_text=$q$Especially with the recent attack on transgender student-athletes with the passage of SB 1165, the Arizona State Legislature is actively perpetuating discrimination in our schools, and as a state representative, I will fight to remove and prevent measures that discriminate against marginalized students.$q$);

-- Aaron Márquez / abortion=2
INSERT INTO essentials.quotes (politician_id, topic_key, quote_text, deidentified_text, source_url, source_name, readrank_selected, editor_note, created_at, updated_at)
SELECT '0df9cd85-3923-48bd-86c2-b7d4b31d510d', 'abortion', $q$Protecting Arizona patients and providers in a post-Roe America starts with repealing archaic and barbaric state laws put on the books by the state's territorial government and the fifteen-week abortion ban signed into law this year by Doug Ducey.$q$, $q$Protecting Arizona patients and providers in a post-Roe America starts with repealing archaic and barbaric state laws put on the books by the state's territorial government and the fifteen-week abortion ban signed into law this year by [the governor at the time].$q$, 'https://www.aaronmarquez.com/issues', 'Aaron Marquez campaign site', true, $q$Verbatim from the candidate's own campaign issues page; only edit was replacing the named former governor with a bracketed description so the quote can't identify the speaker via a dated reference. Cited because it commits specifically to repealing the state's 15-week abortion ban, matching the second-trimester-access chair on the abortion scale.$q$, now(), now()
WHERE NOT EXISTS (SELECT 1 FROM essentials.quotes WHERE politician_id='0df9cd85-3923-48bd-86c2-b7d4b31d510d' AND topic_key='abortion' AND quote_text=$q$Protecting Arizona patients and providers in a post-Roe America starts with repealing archaic and barbaric state laws put on the books by the state's territorial government and the fifteen-week abortion ban signed into law this year by Doug Ducey.$q$);

COMMIT;

